head.b:skin:
/*
-----------------------------------------------
Theme Name	: Dark Blue HD Movie
Style		: 5 Column
Version		: 1.0
Date		: 10-August-2017
Author URL	: http://www.rithiseth.com
License		: Premium Version 
----------------------------------------------- */

/* Variable definitions
   ====================
<Variable name="keycolor" description="Main Color" type="color" default="#1ec7e9" value="#e91e62"/>
<Variable name="body.background" description="Body Background" type="background" color="$(body.background.color)" default="$(color) url() no-repeat fixed top center" value="$(color) url(http://4.bp.blogspot.com/-6uYx-5gqNuw/W0dmXJqqA5I/AAAAAAAAAGM/RJdGFBPT04I8BAte12uQHsx23YN9qqu2ACK4BGAYYCw/s0/body-search.jpg) repeat scroll top center"/>
<Variable name="body.background.override" description="Body Background Override" type="string" default="" value=""/>
<Variable name="startSide" description="Side where text starts in blog language" type="automatic" default="left"/>
<Variable name="endSide" description="Side where text ends in blog language" type="automatic" default="right"/>
<Variable name="before.color" description="Before Color" type="color" default="#D81B60" value="#dd0a4f"/>
<Variable name="headingfont" description="Heading Font"
type="font" default="normal normal 100% 'Rajdhani', sans-serif" value="normal normal 100% &#39;Rajdhani&#39;, sans-serif"/>  

<Group description="Main Backgrounds" selector="body, #outer-wrapper">
	<Variable name="body.background.color" description="Outer Background" type="color" default="#222" value="#222222"/>
	<Variable name="wrapper.background.color" description="Main Background" type="color" default="#3A3A3A" value="#3a3a3a"/>
</Group>

<Group description="Header Title" selector="#header">
	<Variable name="head.font.type" description="Blog Title" type="font" default="normal normal 35px 'Kantumruy','Rajdhani', sans-serif" value="normal normal 35px &#39;Kantumruy&#39;,&#39;Rajdhani&#39;, sans-serif"/>
	<Variable name="head.descfont.type" description="Blog Description" type="font" default="normal normal 12px 'Kantumruy','Rajdhani', sans-serif" value="normal normal 12px &#39;Kantumruy&#39;,&#39;Rajdhani&#39;, sans-serif"/>
	<Variable name="head.font.color" description="Blog Title Color" type="color" default="#333333" value="#333333"/>
	<Variable name="head.descfont.color" description="Blog Description Color" type="color" default="#3D3D3D" value="#3d3d3d"/>	
</Group>

<Group description="Main Menu" selector="#nav">
	<Variable name="menu.font.type" description="Font Type" type="font" default="normal normal 16px 'Kantumruy','Rajdhani', sans-serif" value="normal normal 16px &#39;Kantumruy&#39;,&#39;Rajdhani&#39;, sans-serif"/>
	<Variable name="menu.background.color" description="Background Color" type="color" default="rgba(25, 35, 45, 0.9)" value="rgba(45,25,25,0.898)"/>
    <Variable name="menu.home.color" description="Home Background Color" type="color" default="#1ec7e9" value="#e91e62"/>
	<Variable name="menu.text.color" description="Text Color" type="color" default="#ffffff" value="#ffffff"/>
    <Variable name="menu.borderbottom.color" description="Border Bottom Color" type="color" default="#1ec7e9" value="#e91e62"/>
</Group>

<Group description="Links" selector="body">
	<Variable name="link.color" description="Link Color" type="color" default="#1ec7e9" value="#e91e62"/>
	<Variable name="link.visited.color" description="Visited Color" type="color" default="#1ec7e9" value="#e91e62"/>
	<Variable name="link.hover.color" description="Hover Color" type="color" default="#666666" value="#666666"/>
</Group>

<Group description="Back to Top" selector=".smoothscroll-top">
	<Variable name="scroll.background.color" description="Background Color" type="color" default="#1ec7e9" value="#e91e62"/>
	<Variable name="scroll.icon.color" description="Icon Color" type="color" default="#fff" value="#ffffff"/>
	<Variable name="scroll.hoverbackground.color" description="Background Hover Color" type="color" default="#444" value="#444444"/>
</Group>

<Group description="Search Box" selector="#searchkh">
	<Variable name="search.background.color" description="Submit Background Color" type="color" default="#1ec7e9" value="#e91e62"/>
	<Variable name="search.main.background.color" description="Background Color" type="color" default="#222" value="#222222"/>
	<Variable name="search.text.color" description="Text Color" type="color" default="#fff" value="#ffffff"/>
</Group>

<Group description="Footer" selector="#footer-wrapper">
	<Variable name="footer.bordertop.color" description="Border Top Color" type="color" default="#1ec7e9" value="#e91e62"/>
	<Variable name="footer.text.color" description="Text Color" type="color" default="#fff" value="#ffffff"/>
</Group>

*/

/* CSS Reset Stylesheet
----------------------------------------------- */
/* http://meyerweb.com/eric/tools/css/reset/ 
   v2.0 | 20110126
   License: none (public domain)
*/
html, body, div, span, applet, object, iframe, h1, h2, h3, h4, h5, h6, p, blockquote, pre, a, abbr, acronym, address, big, cite, code, del, dfn, em, img, ins, kbd, q, s, samp, small, strike, strong, sub, sup, tt, var, b, u, i, center, dl, dt, dd, ol, ul, li, fieldset, form, label, legend, table, caption, tbody, tfoot, thead, tr, th, td, article, aside, canvas, details, embed, figure, figcaption, footer, header, hgroup, menu, nav, output, ruby, section, summary, time, mark, audio, video {margin: 0;padding: 0;border: 0;font-size: 100%;font: inherit;vertical-align: baseline;}

/* HTML5 Display-Role Reset for Older Browsers
----------------------------------------------- */
article, aside, details, figcaption, figure, 
footer, header, hgroup, menu, nav, section {display: block;}
body {line-height: 1;}
ol, ul {list-style: none;}
blockquote, q {quotes: none;}
blockquote:before, blockquote:after,
q:before, q:after {content: '';content: none;}
table {border-collapse: collapse;border-spacing: 0;}

/* Elements
----------------------------------------------- */
#navbar-iframe {display:none !important;}
header, nav, section, aside, article, footer {display:block;}
.quickedit{display:none;}
.feed-links{display:none;}
a:hover, a:active, a:focus {outline: 0;}
a:link:hover {text-decoration:none;}
a:link{color:$(link.color);text-decoration:none;outline:none;transition:all 0.5s;-moz-transition:all 0.5s;-webkit-transition:all 0.5s;}
a:visited{color:$(link.visited.color);text-decoration:none;}
a:hover{color:$(link.hover.color);text-decoration:none;}
a img {border-width:0;}
.section,.widget{margin:0;}

/* Headings
----------------------------------------------- */
h1,h2,h3,h4,h5,h6 {font:$headingfont;text-transform:none;margin:0;}

/* Use this with templates/template-twocol.html
----------------------------------------------- */
body {background-color:$(body.background.color);background-image:url(https://www1.hdonline.eu/wp-content/themes/assets/images/body-search.jpg);margin:0;padding:0;color:#fff;font:x-small Georgia Serif;font-size/* */:/**/small;font-size:/**/small;text-align:center;}

/* Outer-Wrapper
----------------------------------------------- */
#outer-wrapper {width:100%;max-width:1100px;background-color:$(wrapper.background.color);margin:0 auto;padding:0;text-align:$startSide;font:normal normal 12px 'Rajdhani', sans-serif;-moz-box-shadow:0 0 5px #D3D3D3;-moz-box-shadow: 0 0 10px rgba(0, 0, 0, 0.32);
-webkit-box-shadow: 0 0 10px rgba(0, 0, 0, 0.32);
box-shadow: 0 0 10px rgba(0, 0, 0, 0.32);}
#main-content {width:100%;padding:0px;float:$startSide;word-wrap:break-word;overflow:hidden;}
#content-wrapper {padding:15px 0;}

/* Header
----------------------------------------------- */
#header-wrapper {margin: 0 auto;overflow: hidden;background:#272626}
.header {margin: 0px 0 20px;float:left;}
.header h1.title,.header p.title {font: $(head.font.type);margin: 0 0 0 0;text-transform: uppercase;color: $(head.font.color);top:10px;position:relative;left:5px;}
.header .description {color: $(head.descfont.color);top:3px;position:relative;font: $(head.descfont.type);}
.header img{top:0px;}
.header a {padding-top:20px;color: #333333;}
.header a:hover {color: $keycolor;}
#header-right{float:right;margin:20px 7px;width:728px}
#ads-top{float:none;margin:0 auto;padding:0px;width:100%;max-width:1100px}
#ads-bottom{float:none;margin:0 auto;padding:0px;width:100%;max-width:1100px}

/* Top Navigation
----------------------------------------------- */
#topnav {background:#1A1A1A;padding:0;height: 29px;font-size:11px;position: relative;}
#topnav .wrapkh, #nav .wrap,
#headiz, #content-wrapper {margin:0 auto;width:98%;}
#topnav .tgltop {float:$startSide;color:#E2E2E2;display:block;line-height:20px;margin-top: 4px;}

/* Main Navigation
----------------------------------------------- */
#nav {height:50px;position:relative;z-index:1;}
#nav .sethbg {width:100%; background-color:$(menu.background.color);height:46px;position:absolute;z-index:-1;bottom:0;left:0;border-bottom:4px solid $(menu.borderbottom.color);}
.kh-menu, .kh-menu * {margin:0;padding:0;list-style:none;}
.kh-menu li {position:relative;}
.kh-menu ul {position:absolute;display:none;top:100%;left:0;z-index:99;}
.kh-menu > li {float:$startSide;margin:0 1px;}
.kh-menu li:hover > ul, .kh-menu li.khHover > ul {display:block;}
.kh-menu a {display:block;position:relative;}
#menunav > li > a {font: $(menu.font.type);line-height: 50px;text-transform: uppercase;font-weight: 600;height: 50px;}
.kh-menu ul ul {top:0;left:100%;}
.kh-menu {float:$startSide;}
.kh-menu ul {min-width:16em;*width:16em;border-bottom: 4px solid $keycolor;}
.kh-menu a {padding:0 10px;height:50px;line-height:50px;text-decoration:none;zoom:1;}
.kh-menu a.home, .kh-menu > li > a.home.current {background-color:$(menu.home.color);text-indent:-9999px;padding:0px;width:50px;}
.kh-menu a {color:$(menu.text.color);font-size:16px;}
#topnav .kh-menu a {color:#fff;height: 29px;line-height: 29px;}
.kh-menu li {white-space:nowrap;*white-space:normal;-moz-transition:background-color .2s;-webkit-transition:background-color .2s;transition:background-color .2s;position:relative;}
.kh-menu ul li {background-color:#2E2E2E;margin:0px 0;border-top: 1px solid #333;-moz-border-radius: 0px;-webkit-border-radius: 0px;border-radius: 0px;}
.kh-menu ul li:hover{box-shadow:inset 4px 0 $keycolor;transition:all .3s;}
#topnav .kh-menu ul li, #topnav .kh-menu ul ul li {background-color:#1A1A1A;}
.kh-menu ul a {font-weight:normal;height:40px;line-height:40px;}
#topnav .kh-menu ul a {height:25px;line-height:25px;}
.kh-menu ul a:hover {padding-left:12px;}
.kh-menu ul ul li {background:#2E2E2E;margin:0 0 0 2px;}
.kh-menu li:hover > a, .kh-menu li.khHover > a, .kh-menu > li > a.current {background-color:rgba(255,255,255,0.1);-moz-transition:none;-webkit-transition:none;transition:none;color:#E6E6E6;}
#topnav .kh-menu li:hover > a, #topnav .kh-menu li.khHover > a, #topnav .kh-menu > li > a.current {background-color:$keycolor;color:#E2E2E2;}
.kh-arrows .kh-with-ul {padding-right:2em;*padding-right:1em;}
.kh-arrows .kh-with-ul:after {content:'';position:absolute;top:50%;right:0.85em;margin-top:-2px;height:0;width:0;border:4px solid transparent;border-top-color:#E6E6E6;}
#topnav .kh-arrows .kh-with-ul:after  {border-top-color:#fff;}
.kh-arrows > li > .kh-with-ul:focus:after, .kh-arrows > li:hover > .kh-with-ul:after, .kh-arrows > .khHover > .kh-with-ul:after {border-top-color:#E6E6E6;}
#topnav .kh-arrows > li > .kh-with-ul:focus:after, #topnav .kh-arrows > li:hover > .kh-with-ul:after, #topnav .kh-arrows > .khHover > .kh-with-ul:after {border-top-color:#E2E2E2;}
.kh-arrows ul .kh-with-ul:after {margin-top:-4px;margin-right:-3px;border-color:transparent;border-left-color:#E6E6E6;}
#topnav .kh-arrows ul .kh-with-ul:after {border-left-color:$keycolor;}
.kh-arrows ul li > .kh-with-ul:focus:after, .kh-arrows ul li:hover > .kh-with-ul:after, .kh-arrows ul .khHover > .kh-with-ul:after{border-left-color:#E6E6E6;}
#topnav .kh-arrows ul li > .kh-with-ul:focus:after, #topnav .kh-arrows ul li:hover > .kh-with-ul:after, #topnav .kh-arrows ul .khHover > .kh-with-ul:after {border-left-color:#E2E2E2;}
.kh-menu li > i {position:absolute;top: 3px;right: 3px;width: 27px;height: 22px;cursor:pointer;display:none;background-color:$keycolor;-moz-border-radius:2px;-webkit-border-radius:2px;border-radius:2px;outline:0;}
.kh-menu li > i:after {content: '\f107';font-family: FontAwesome;color: #fff;font-size: 19px;position: absolute;left: 7px;top:0px;}
.kh-menu li > i.active:after {content:'-';font-size:39px;top:-15px;}
#topnav .kh-menu li > i {width: 23px;height: 19px;top: 6px;}
#topnav .kh-menu li > i:after {top: -1px;left: 5px;}
#topnav .kh-menu li > i.active:after {top: -12px;font-size: 31px;left: 6px;}
.kh-menu a.home:before, #searchkh button:before, #view a:before, .rcentpost .date:before, .rcentpost .comnum:before, .morepostag a:before, #topmobilenav:before, #mobilenav:before, #related_posts .date:before, #related_posts .comnum:before {position: absolute;font-family: FontAwesome;font-weight: normal;font-style: normal;text-decoration: inherit;-webkit-font-smoothing: antialiased;}
.kh-menu a.home:before, #searchkh button:before, #view a:before, .breadcrumbs .homex:before {text-indent: 0;}
.kh-menu a.home:before {width: 30px;height: 30px;}
.kh-menu a.home:before {content: "\f015";top: 0;font-size: 27px;left: 13px;color: #FBFBFB;}
#searchkh button:before {content: "\f002";top: 8px;left: 16px;color: #E6E6E6;font-size: 18px;}
#topmobilenav:before, #mobilenav:before {content: "\f0c9";top: 10px;text-indent: 0;left: 14px;font-size: 25px;}
#topmobilenav:before {font-size: 17px;top: 5px;left: 10px;}
#topmobilenav, #mobilenav {position: absolute;width: 50px;height: 50px;left:0px;bottom:0px;color: #E6E6E6;text-decoration: none;text-indent: -9999px;outline:0;background-color:$keycolor;}
#topmobilenav {width: 35px;height: 29px;bottom:0px;color:#E2E2E2;}
#mobilenav.active {color:rgba(25, 35, 45, 0.9);}
#topmobilenav.active {color: #1A1A1A;}

/* Social Icons
----------------------------------------------- */
ul.nav-social li{display:inline-block;list-style-type:none;float:right;margin:0 0;padding:0 0;border-right:none;margin-top:-1px;}
ul.nav-social li a{display:inline-block;line-height:30px;height:30px;padding:0 4px;margin-left:2px;color:#666666;}
ul.nav-social li a i{line-height:30px;color:#fff;}
ul.nav-social li a.fcb,
ul.nav-social li a.gpl,
ul.nav-social li a.twt,
ul.nav-social li a.ytb,
ul.nav-social li a.ins{background:transparent;opacity:12;width:15px;text-align:center;font-size:15px}
ul.nav-social li a:hover{opacity:80}

/* Posts Outer Wrapper
----------------------------------------------- */
.blog-posts.hfeed {overflow:hidden;}
.index .post-outer, .archive .post-outer {width:16.66666%;float:$startSide;position:relative;}
.index .post-outer .post, .archive .post-outer .post {margin:0 8px 8px 11px;height:250px;position:relative;z-index:0;}
.index .post-outer.list, .archive .post-outer.list {width:100%;float:none;}
.index .post-outer.list .post, .archive .post-outer.list .post {height:auto;margin:0 0 15px;padding-bottom:10px;}
.index .post h2.post-title, .archive .post h2.post-title, #topmobilenav, #mobilenav, #topmenunya h2 {display:none;}
a.thumbimgx{display:block;border:0px solid #C0C0C0;-moz-border-radius:3px;-webkit-border-radius:3px;border-radius:4px;height:200px;margin-bottom:10px;margin-top:8px;padding: 0px;overflow:hidden;position:relative;background-color:#fff;}
a.thumbimgx:hover:before{opacity:1;transform:scale(1.5,1.5)}
a.thumbimgx:before{font-family:FontAwesome;content:"";z-index:1;height:100%;width:100%;background:rgba(0,0,0,0.65);opacity:0;position:absolute;top:0;left:0;border-radius:0%;transform:scale(0,0);transition:all .7s;}
a.thumbimgx:after:before, #feedContainer .inner:before, #feedContainer .inner:after, ul.rcentpost > li.a0 a.thumbxtag:before, .rcbytag.s ul.rcentpost a.thumbxtag:before, ul.rcentpost > li.a0 a.thumbxtag:after, .rcbytag.s ul.rcentpost a.thumbxtag:after {content:"";position:absolute;z-index:-2;bottom:15px;left:5px;width:50%;height:20%;max-width:300px;}
a.thumbimgx:after, #feedContainer .inner:after, ul.rcentpost > li.a0 a.thumbxtag:after, .rcbytag.s ul.rcentpost a.thumbxtag:after {.right:5px;left:auto;-webkit-transform:rotate(3deg);-moz-transform:rotate(3deg);-ms-transform:rotate(3deg);-o-transform:rotate(3deg);transform:rotate(3deg);}
a.thumbimgx img{height: 100%;width: 100%;}
.post h1.post-title, .post h2.post-title{font-size:155%;font-weight:600;border-bottom:0px solid #C0C0C0;padding:0px;color:#141414;margin-bottom:8px;text-align:center;position:relative;}
.post h1.post-title a:before, .post h1.post-title a:after {position:absolute;top:50%;overflow:hidden;width:50%;height:5px;margin-top:-3px;content:'\a0';background-color:$keycolor;}
.post h1.post-title a:before{margin-left:-51%;text-align:right;}
.post h1.post-title a:after{margin-left:1%;text-align:left;}
.post h2.post-title{padding-left:0;}
.post h1.post-title a, .post h2.post-title a {text-decoration:none;display:block;color:$keycolor;}
.post-body {margin:0 0 .75em;line-height:1.6em;font-family:'Hanuman','Roboto Condensed';font-size: 14px;}
.widget .post-body ul{padding:0px}
.post-body iframe {max-width: 100%;}
.item .post-body img, .static_page .post-body img {max-width:99%;}
.item .post-footer, .static_page .post-footer {display:block;border-top:0px solid #C0C0C0;padding:8px;margin:0 -10px -10px;background-color:transparent;}
.tr-caption-container img {border:none;padding:0;}
.post-timestamp {display:none;}
.post-author.vcard, .post-labels {margin-bottom:5px;}
.post-footer .item-control.blog-admin.pid-1748668997 {float:$endSide;}
.post blockquote p {margin:.75em 0;}
.post-summary p, .post-more-link, .post-footer {display:none;}
.post .titlex, ul.rcentpost li strong a {text-decoration:none;font:normal normal 13px 'Rajdhani', sans-serif;font-weight:600;text-align: center;line-height:1.7em;color:#fff;display:block;margin:0;max-height:36px;overflow:hidden;font-family: 'kantumruy';}
.titlex:before{content: "\f144";margin:2px;font:normal normal normal 12px/1 FontAwesome;color:$keycolor;}
.post-outer.list a.thumbimgx{width:200px;float:$startSide;margin:0 10px 0 5px;}
.post-outer.list .post .titlex {font-size:150%;max-height:200px;margin:0;overflow:visible;}
.post-outer.list .post-summary p {display:block;margin:10px 0 0;}
.post-outer.list .post-more-link {display:block;position:absolute;bottom:0;float:$endSide;right:0;}
.post-outer.list .post-more-link a {display:block;text-decoration:none;padding:4px 8px;font-size:90%;background-color:$keycolor;color:#fff;}
.post-outer.list .post-more-link a:hover {background-color:#2E2E2E;}

/* Posts Body Wrapper
----------------------------------------------- */
.post-body .left {float:$startSide;margin:0 5px 5px 0;}
.post-body .right {float:none;margin:0 0 5px 5px;}
.post-body .center {margin:10px 0 15px 0;display:block;text-align:center;}
.post-body .left span, .post-body .right span, .post-body .center span {.display: block;text-align: center;font-size: 80%;font-style: italic;}
.post-body blockquote {padding-left:40px;margin:20px;font-size:110%;line-height:1.6em;color:#777;background:url(http://1.bp.blogspot.com/-sJbFLVX5LVs/UDzoGxMvWrI/AAAAAAAAAmg/qkUni125BV0/s1600/quotation-l.png) no-repeat left 5px;}
.post-body h1 {font-size:180%;}
.post-body h2 {font-size:160%;}
.post-body h3 {font-size:140%;}
.post-body h4 {font-size:130%;}
.post-body h5 {font-size:120%;}
.post-body h6 {font-size:110%;}
.main .Blog {border-bottom-width:0;position: relative;}
#main-wrapper .inline-ad {text-align: center;padding: 10px 0;overflow: hidden;}
.item .post-body img, .static_page .post-body img {padding:4px;border:1px solid #000;}
.item .post, .static_page .post, .comments .comments-content, #related_posts ul, .boxcommentnya, #main-wrapper .inline-ad {padding:10px;border:1px solid #4D4F50;position:relative;margin:0 0 10px;background-color:transparent;-moz-border-radius:2px;webkit-border-radius:2px;border-radius:2px;}

/* Sidebar Wrapper
----------------------------------------------- */
#sidebar-wrapper {width:33%;float:right;padding:0px;word-wrap:break-word;overflow:hidden;display:none}
.sidebar .widget > h2{position:relative;overflow:hidden;font-size:120%;font-weight:700;padding:0px;margin-bottom: 8px;text-align:center;text-transform:uppercase;transition:all .5s ease-out;}
.sidebar .widget > h2:before, .sidebar .widget > h2:after {position:absolute;top:51%;overflow:hidden;width:50%;height:1px;content: '\a0';
border: 1px dotted #a3a7ac;}
.sidebar .widget > h2:before{margin-left:-50%;text-align:right;}
.sidebar .widget > h2 span{background: #313030;color:#fff;border-radius:2px;position:relative;display:inline-block;padding:5px 10px;margin:0 5px;z-index: 1 !important;}
.sidebar .widget > h2 span:before{content:"\f09e";font-family:Fontawesome;display:inline-block;text-align:center;margin-right:5px;font-weight:normal}
.sidebar {color:#666;line-height:1.5em;}
.sidebar ul{list-style:none;margin:0 0 0;padding:0 0 0;}
.sidebar li{margin:0;padding-top:0;padding-$endSide:0;padding-bottom:.25em;padding-$startSide:0px;line-height:1.5em;}
.sidebar .widget{margin:0 0 0.5em;padding:0 10px;}
.sidebar #HTML1 h2 span:before{content:"\f2b5";font-family:Fontawesome;display:inline-block;text-align:center;margin-right:5px;font-weight:normal}
.sidebar #HTML2 h2 span:before{content:"\f1e0";font-family:Fontawesome;display:inline-block;text-align:center;margin-right:5px;font-weight:normal}
.sidebar #HTML4 h2 span:before{content:"\f0ca";font-family:Fontawesome;display:inline-block;text-align:center;margin-right:5px;font-weight:normal}
.sidebar #PopularPosts1 h2 span:before{content:"\f03d";font-family:Fontawesome;display:inline-block;text-align:center;margin-right:5px;font-weight:normal}

/* Breadcrumb
----------------------------------------------- */
.breadcrumbs{background:$keycolor;padding:15px 20px 15px 65px;margin-bottom:0px;font-size:14px;color:#fff;font-weight:600;position:relative;}
.breadcrumbs a{color:#fff;text-decoration:none;}
.breadcrumbs a:hover{color:#2F2F2F;text-decoration:none;}
.breadcrumbs:before {content: "\f041";font-family:fontAwesome;font-size:17px;font-style: normal;background-color:$(before.color);color:#fff;top:0;left:0;padding:13px 21px;position:absolute;}

/* Share Button
----------------------------------------------- */
h3.sharetitle span{border: 1px solid #2F3133;color:#fff;background:#313030;border-radius:3px;}
h3.sharetitle{position:relative;overflow:hidden;font-size:120%;font-weight:600;font-size:14px;padding:4px 8px;text-align:center;text-transform:uppercase;transition:all .5s ease-out;}
h3.sharetitle:before, h3.sharetitle:after {position:absolute;top:51%;overflow:hidden;width:50%;height:1px;content: '\a0';
border: 1px dotted #a3a7ac;}
h3.sharetitle:before{margin-left:-50%;text-align:right;}
h3.sharetitle span{position:relative;display:inline-block;padding:5px 10px;margin:0 5px;}
.sharede,.sharebrow{position:relative;display:inline-block;}
.sharebrow a.gp {background:#f20000;}
.sharebrow a.fb {background:#516ca4;}
.sharebrow a.tw {background:#00baff;}
.sharebrow span.pl {background:#ff6600;}
.sharebrow{display:table;margin:auto;text-align:center}
.sharebrow a.fb,.sharebrow a.gp,.sharebrow a.tw,.sharebrow span.pl{text-decoration:none!important;display:inline-block;margin:0 5px 5px 0;font-weight:400;font-size:14px;color:#fff;padding:4px 10px;transition:all .3s;border-radius: 2px;}
.fbtea,.gotea,.plustea,.twtea{font-size:13px!important;vertical-align:middle}
.sharebrow a.fb:hover,.sharebrow a.gp:hover,.sharebrow a.tw:hover,.sharebrow span.pl:hover{color:#fff;border-color:#fff;}
.sharebrow a.fb:active,.sharebrow a.gp:active,.sharebrow a.tw:active,.sharebrow span.pl:active{box-shadow:inset 0 1px 0 rgba(0,0,0,.16)}
span.pl{color:green;cursor:pointer}
#share-menu{display:none}
.dropdown-menu{position:absolute;bottom:100%;right:5px;z-index:99;float:left;min-width:100px;padding:5px 10px;margin:0;font-size:13px;text-align:left;list-style:none;background-color:#fff;-webkit-background-clip:padding-box;background-clip:padding-box;border:1px solid #ddd;border-radius:3px;}
.dropdown-menu li{list-style:none!important;margin:0!important;padding-left:0!important;line-height:1.8em!important}
.dropdown-menu li a{color:#333!important;font-weight:400;display:block}
.dropdown-menu li a:hover{color:#e8554e!important}
ul#share-menu{margin:10px 0;padding:5px 15px}

/* Comments
----------------------------------------------- */
.comments{display:none;}
.comment-form {max-width:100%;padding:10px;border:1px solid #C0C0C0;margin:0 0 10px;-moz-border-radius:2px;webkit-border-radius:2px;border-radius:2px;}
.comments.threaded_commentsnya .comment-form {display:none;}
.comments .continue a, .comments .comments-content .comment-thread ol .comment-replybox-thread {-moz-box-shadow:inset 0 1px 5px #CACACA;-webkit-box-shadow:inset 0 1px 5px #CACACA;box-shadow:inset 0 1px 5px #CACACA;background-color:#FAFAFA;}
.comments .comments-content .comment-thread ol .comment-replybox-thread #form-wrapper {padding:5px 10px;}
.comments .comments-content .comment-thread ol {margin:0;}
.comments .comments-content .inline-thread {border:1px solid #E9E6E6;border-left:2px solid #1ec7e9;-moz-border-radius:3px;-webkit-border-radius:3px;border-radius:3px;}
.comments .comments-content .comment:first-child {padding-top:0;}
.comments .comments-content .inline-thread .comment:first-child {padding-top:12px;}
.comments .comments-content .icon.blog-author, .commentarea .author-comment {background-image:url(http://3.bp.blogspot.com/-TpMivpUpG0s/UXCpktVApyI/AAAAAAAAI-o/6ZzgqgrANLI/s17/48_edit.png);background-repeat:no-repeat;background-position:50% 50%;}
#comments-block .avatar-image-container img {width:35px;height:35px;display:block;}
#comments-block .avatar-image-container.avatar-stock img {border-width:0;padding:1px;background-image:url(http://4.bp.blogspot.com/-AEWksK942OE/UFiyLzXJhiI/AAAAAAAAFKE/jBegaGPClxI/s37/user-anonymous-icon.png);}
.comments .comments-content .comment-content {text-align:justify;line-height:1.6em;}
#comments-block.avatar-comment-indent dd.comment-body p {margin:0;line-height:1.6em;}
#comments-block .avatar-image-container {top:0;}
.commentarea {padding:8px;border:1px solid #E9E6E6;border-left:2px solid #1ec7e9;-moz-border-radius:3px;-webkit-border-radius:3px;border-radius:3px;margin:0 0 15px;position:relative;}
#comments-block.avatar-comment-indent dd.comment-body {margin:10px 0;}
#comments-block.avatar-comment-indent .commentarea .comment-footer {margin-bottom:0;text-align:right;}
.commentarea .datecm {font-size:90%;float:$endSide;}
.commentarea .author-comment {display:inline-block;height:18px;margin:0 6px -4px 0;width:18px;}
#googlePlusComment, .cmt_iframe_holder {width:100% !important;}

/* Popular Posts
----------------------------------------------- */
.popular-posts ul li {float:right;width:50%;list-style-type:none;border:none;line-height:13px;text-align: center;}
.item-thumbnail{text-align:center;}
.popular-posts ul li img {width: 160;height: 160px;border-radius:11px;background: transparent;padding: 8px;margin-top: 10px;margin-right: 10px;}
.PopularPosts .item-title a{overflow: hidden;display: inline-block;height: 28px;font-size: 14px;font-weight:400;text-align: center;color:#fff}
.PopularPosts .item-thumbnail{margin:-26px 15px 0 0;}
.PopularPosts .item-title a:before{content: "\f04b";margin:2px;font:normal normal normal 12px/1 FontAwesome;color:$keycolor;}

/* Recommendation Slide Box
----------------------------------------------- */
#sliding_box{background:#fff3;max-width:310px;width:100%;height:185px;overflow:hidden;border:none;position:fixed;right:-360px;text-align:left;z-index:99;box-shadow:0 2px 5px 0 rgba(0,0,0,0.16),0 2px 10px 0 rgba(0,0,0,0.12);transition:all .4s ease-out}
.sliding_box-title{background:$keycolor;display:block;height:45px;color:#fff;line-height:45px;text-transform:capitalize;width:100%;font-size:14px;font-weight:500;letter-spacing:.5px}
.sliding_box-title span a{text-align:center;color:#fff;font-family:initial;float:right;height:40px;margin:0 0 0 15px;font-size:20px}
a#sliding_box-close,a#sliding_box-close{margin-right:15px}
.sliding_box-title >span >h2{font-weight:normal!important;font-size:20px!important;}
.sliding_box-container{width:100%;height:auto;border:none;float:left;margin:3px}
.sliding_box-container >div{padding:10px 0;border:none;margin:3px 0;}
.sliding_box-container >div >span{font-size:14px}
.show{bottom:84px}
.hide{bottom:-145px}
.related-post{font-size:70%}
.related-post h4{font-size:150%;margin:0 0 .5em}
.related-post-style-2{list-style:none;margin-top:-20px;padding-top:15px}
.related-post-style-2 li{overflow:hidden;padding:0 10px 10px 10px;}
.related-post-style-2 li:first-child{border-top:none}
.related-post-style-2 .related-post-item-thumbnail{float:left;margin:2px 10px 0 0;max-width:none;max-height:none;height:45px;border:0;padding:0;width:45px;border-radius:3px;}
.related-post-style-2 .related-post-item-title{font-size:130%;line-height:normal;font-size:13px;}
a.related-post-item-title{transition:all .4s ease-out;color:#fff;font-size:20px;}
a:hover.related-post-item-title{text-decoration:none;color:$keycolor;}
.related-post-style-2 .related-post-item-summary{overflow:hidden;display:block;}

/* Page Navigation Number
----------------------------------------------- */
.pagenavi{clear:both;margin:0 5px 0px 10px;text-align:center;font-weight:600;color:#fff!important;text-transform:uppercase;border-top: 0px double $keycolor;margin-top: -5px;padding:10px;}
.pagenavi span,.pagenavi a{padding:8px 16px;margin-right:3px;display:inline-block;color:#fff!important;background-color:transparent;border:2px solid $keycolor}
.pagenavi .current{color:#fff!important;background:$keycolor;border:1px solid $keycolor;padding: 9px 18px;}
.pagenavi .pages,.pagenavi a:hover{color:#222!important;border:2px solid #222;text-decoration:none;transition: .8s ease-out;}
.pagenavi .pages {display:none}

/* Youtube Responsive
----------------------------------------------- */
.videoresp {position: relative;padding-bottom:50%;padding-top:20px;overflow: hidden;max-width: 100%;height: auto;margin: 0px auto;}
.videoresp iframe, .videoresp object, .videoresp embed {position: absolute;top: 0;left: 0;width: 100%;height: 100%;}

/* Notification
----------------------------------------------- */
#notification{border-bottom: 1px solid $keycolor;padding: 8px 10px;font-size: 16px;font-weight:600;color: #613115;background: rgba(51, 74, 125, 0.22);text-indent: 22px;text-align:center;margin-top: 2px;}
#notification a{color:#fff}
.close-button{display:block;width:16px;float:right;margin-right:19px;margin-top:-2px;opacity:.7}
.close-button:hover{opacity:1;cursor:pointer}

.menu-xitem {background-image:url(http://2.bp.blogspot.com/-QSzTaScBXO0/U7Zu2AoaS4I/AAAAAAAAB_0/tbhtPKsuWTo/s1600/footer-bg.png);background-repeat:repeat-x;background-position:0 50%;height:34px;margin:0px 11px -5px 11px;}

/* Disclaimer Box
----------------------------------------------- */
.disbox{padding: 10px;line-height: 22px;font-size: 14px;background-color: #2F3133;color:#fff;border-top: 2px solid $keycolor;border-bottom: 2px solid $keycolor; margin-top: 5px;text-align:justify}

/* Related Posts2
----------------------------------------------- */
#related-post h4{background:#f9f9f9;border-bottom:2px solid $keycolor;border-right:0;line-height:32px;font-size:14px;text-transform:uppercase;font-weight:600;}
#related-post h4 span{display:inline-block;padding:2px 12px 0;background-color:$keycolor;color:#fff}

/* Responsive Facebook Comment
----------------------------------------------- */
.comment-fb {margin:0px 8px 0px 8px;padding:0;position:relative;}
.comment-fb h2{background:#f9f9f9;border-bottom:2px solid $keycolor;border-right:0;line-height:32px;font-size:14px;text-transform:uppercase;font-weight:600;}
.comment-fb h2 span{display:inline-block;padding:2px 12px 0;background-color:$keycolor;color:#fff}
.comment-fb h2 span:before{content:"\f230";font-family:Fontawesome;display:inline-block;text-align:center;margin-right:5px;font-weight:normal}

/* Menu Icons 
----------------------------------------------- */
movie:before{content:"\f152";font:normal normal normal 13px/1 FontAwesome;color:#FD096E;margin-right: 5px;display: inline-block;height: 26px;text-align: center;/* margin: 0; */padding: 0;width: 26px;font-size: 12px;color: #fff;position: relative;z-index: 10;background: $keycolor;line-height: 27px;}
drama:before{content:"\f144";font:normal normal normal 13px/1 FontAwesome;color:#FD096E;margin-right: 5px;display: inline-block;height: 26px;text-align: center;/* margin: 0; */padding: 0;width: 26px;font-size: 12px;color: #fff;position: relative;z-index: 10;background: $keycolor;line-height: 27px;}
tenfi:before{content:"\f118";font:normal normal normal 13px/1 FontAwesome;color:#FD096E;margin-right: 5px;display: inline-block;height: 26px;text-align: center;/* margin: 0; */padding: 0;width: 26px;font-size: 12px;color: #fff;position: relative;z-index: 10;background: $keycolor;line-height: 27px;}
cartoon:before{content:"\f04b";font:normal normal normal 13px/1 FontAwesome;color:#FD096E;margin-right: 5px;display: inline-block;height: 26px;text-align: center;/* margin: 0; */padding: 0;width: 26px;font-size: 12px;color: #fff;position: relative;z-index: 10;background: $keycolor;line-height: 27px;}
tv:before{content:"\f26c";font:normal normal normal 13px/1 FontAwesome;color:#FD096E;margin-right: 5px;display: inline-block;height: 26px;text-align: center;/* margin: 0; */padding: 0;width: 26px;font-size: 12px;color: #fff;position: relative;z-index: 10;background: $keycolor;line-height: 27px;}

/* Movie Form Category
----------------------------------------------- */
a.profile:after {content: 'Recommended';color: $keycolor;font-size: 14px;padding: 2px;font-weight: bold;border: 1px dotted;margin: -5px 7px;}
ul.form{position:relative;background:transparent;width:100%;margin:auto;padding:0;list-style:none;}
.form li a{border: 1px solid #4D4F50;width: 100%;height: 35px;display: block;position: relative;text-decoration: none;text-transform: uppercase;font-size:14px;color: #999;-webkit-transition: all .2s linear;-moz-transition: all .2s linear;-o-transition: all .2s linear;transition: all .2s linear;}
.form li a:hover{ color: $keycolor;text-decoration: none;border-color:$keycolor}
.form li:first-child a:hover,.form li:first-child a{}.form li:last-child a:hover,.form li:last-child a{}.form li a:hover i{color:$keycolor}
.form i{-webkit-transition:all .2s linear;-moz-transition:all .2s linear;-o-transition:all .2s linear;transition:all .2s linear}
.form em{font-size:10px;background:$keycolor;padding:3px 5px;-webkit-border-radius:10px;-moz-border-radius:10px;border-radius:10px;font-style:normal;color:#fff;margin-top:17px;margin-right:15px;line-height:10px;height:10px;float:right}
.form li a i{padding: 11px; font-size: 12pt;border-radius:2px;height: 20px;}
.form li {margin-bottom: 3px;}

/* Search Box
----------------------------------------------- */
#searchkh {float:$endSide;width:250px;margin:10px 0 0;}
#searchkh button {text-indent:-9999px;overflow:hidden;margin-right:0px;background: $(search.background.color);width:50px;height:35px;border-radius:2px;font-size:12px;left:60px;bottom:4px;position:relative;cursor:pointer;border:none !important;outline:none;}
#ajax-search-form {position:relative;font:normal normal 14px 'Rajdhani', sans-serif;width:230px;float:$endSide;}
#ajax-search-form input {color:$(search.text.color);margin:-4px -55px 0;background:$(search.main.background.color);padding:9px 23px;font-family:'Rajdhani', sans-serif;font-weight:600;font-size:14px;outline:0;width:175px;float:$startSide;border:0;}
#ajax-search-form input:focus {color:#FFF;}

/* Search Result
----------------------------------------------- */
#search-result {color:#585858;border:1px solid #F3F3F3;background-color:#151515E6;padding:8px 10px;margin:10px 0;width:280px;height:auto;position:absolute;top:27px;right:10px;z-index:99;-webkit-box-shadow:0 1px 3px #999;-moz-box-shadow:0 1px 3px #999;box-shadow:0 1px 3px #999;display:none;}
#search-result * {margin:0 0 0 0; padding:0 0 0 0;}
#search-result * p{display:none}
#search-result h4, #search-result strong {display:block;margin:0 30px 10px 0;}
#search-result ol {list-style:none;overflow:hidden;padding-right: 15px;}
.box, .box .antiscroll-inner {width: 100%;height: 400px;}
#search-result .close {text-decoration:none;display:block;position:absolute;top:-6px;font-size:50px;right:10px;line-height:normal;color:#fff;}
#search-result li {padding:5px 0;overflow: hidden;}
#search-result strong {font-family:Hanuman,'Rajdhani', sans-serif;margin:0 0 3px 0;display:block;}
#search-result img {float:$startSide;display:block;margin:0 5px 0 0;-moz-border-radius:2px;-webkit-border-radius:2px;border-radius:2px;}

/* Label
----------------------------------------------- */
.label-size-1,.label-size-2,.label-size-3,.label-size-4,.label-size-5 {font-size:100%;filter:alpha(100);opacity:10}
.cloud-label-widget-content{text-align:left}
.label-size {background:$keycolor;display:block;float:left;margin:0 3px 3px 0;color:#fff;font-size: 13px;border-radius: 5px 0 5px 0;text-transform:none;}
.label-size a,.label-size span{display:inline-block;color:#fff;padding:6px 8px;font-weight:bold;}
.label-size:hover {background:#333;border-radius: 0 5px 0 5px;transition:all 0.5s ease-in-out;}
.label-count {white-space:nowrap;padding-right:3px;margin-left:-3px;background:$keycolor;color:#fff !important;}
.label-size {line-height:1.2}

/* Anti-Scroll Bar
----------------------------------------------- */
.antiscroll-wrap {display: block;position: relative;overflow: hidden;}
.antiscroll-scrollbar {background: gray;background: rgba(0, 0, 0, 0.5);-webkit-border-radius: 7px;-moz-border-radius: 7px;border-radius: 7px;-webkit-box-shadow: 0 0 1px #fff;-moz-box-shadow: 0 0 1px #fff;box-shadow: 0 0 1px #fff;position: absolute;opacity: 0;filter: progid:DXImageTransform.Microsoft.Alpha(Opacity=0);-webkit-transition: linear 300ms opacity, linear 300ms width;-moz-transition: linear 300ms opacity, linear 300ms width;-o-transition: linear 300ms opacity, linear 300ms width;transition: linear 300ms opacity, linear 300ms width;}
.antiscroll-scrollbar-shown {opacity: 1;filter: progid:DXImageTransform.Microsoft.Alpha(Opacity=100);}
.antiscroll-scrollbar-horizontal {height: 7px;margin-left: 2px;bottom: 2px;left: 0;}
.antiscroll-scrollbar-vertical {width: 7px;margin-top: 2px;right: 2px;top: 0;}
.antiscroll-scrollbar-vertical:hover {width: 9px;}
.antiscroll-inner {overflow: scroll;}
.antiscroll-inner::-webkit-scrollbar {width: 0;height: 0;}
.antiscroll-inner::scrollbar {width: 0;height: 0;}

/* Scrollbar
----------------------------------------------- */
::-webkit-scrollbar {width: 12px;background-color: #F5F5F5;}
::-webkit-scrollbar-track {-webkit-box-shadow: inset 0 0 50px rgba(0,0,0,0.3);background-color: #F5F5F5;}
::-webkit-scrollbar-thumb {border-radius: 0px;-webkit-box-shadow: inset 0 0 50px rgba(0,0,0,.3);background-color: $keycolor;}
::-webkit-scrollbar-thumb:hover {-webkit-box-shadow: inset 1px 1px 10px rgba(0,0,0,0.3);}

/* Selection
----------------------------------------------- */
::selection{background:$keycolor;color:#FFFFFF;text-shadow:none;}
::-moz-selection{background:$keycolor;color:#FFFFFF;text-shadow:none;}
.highlight{background-color:$keycolor;font-weight:bold;color:#FFFFFF;}

/* Back to Top
----------------------------------------------- */
.smoothscroll-top {position:fixed;opacity:0;visibility:hidden;overflow:hidden;text-align:center;z-index:99;background-color:$(scroll.background.color);color:$(scroll.icon.color);width:47px;height:44px;line-height:44px;right:25px;bottom:-25px;padding-top:2px;border-radius:3px;transition:all 0.5s ease-in-out;transition-delay:0.2s;box-shadow: 0 2px 2px 0 rgba(0, 0, 0, 0.14), 0 1px 5px 0 rgba(0, 0, 0, 0.12), 0 3px 1px -2px rgba(0, 0, 0, 0.2);}
.smoothscroll-top:hover {background-color:$(scroll.hoverbackground.color);color:#fff;transition:all 0.2s ease-in-out;transition-delay:0s;}
.smoothscroll-top.show {visibility:visible;cursor:pointer;opacity:1;bottom:25px;}
.smoothscroll-top i.fa {line-height:inherit;}

/* Archive
----------------------------------------------- */
#table-outer table {width:100%;}
#orderFeedBy, #labelSorter {width:90%;margin:5px 0;}
#postSearcher input[type="text"] {width:88%;margin:5px 0;padding:3px 1%;}
#feedContainer, #feedContainer li {padding:0;margin:0;list-style:none;}
#feedContainer {overflow:hidden;margin-top:20px;}
#feedContainer li {float:left;width:50%;margin-bottom:10px;position:relative;z-index: 0;}
#feedContainer .inner {padding:8px;margin:0 5px;position:relative;background-color:#FFF;border:1px solid #C0C0C0;-moz-border-radius:2px;-webkit-border-radius:2px;border-radius:2px;height:133px;}
#feedContainer img {float:left;margin:0 8px 0 0;}
#feedContainer .inner > strong {display:none;}
#feedContainer .date {position:absolute;top:8px;left:15px;background-color:$keycolor;color:#fff;font-size:9px;padding:3px 2px;}
#feedContainer .inner:hover .date {background-color:#2E2E2E;}
#feedContainer .date span {display:block;line-height:12px;text-align:center;}
#feedContainer .date .dd {font-size:15px;line-height:18px;font-weight:bold;}
#feedContainer .toc-title {max-height:33px;overflow:hidden;}
#feedNav a, #feedNav span {display:block;text-align:center;color:#fff;text-decoration:none;background-color:$keycolor;padding:5px;width:95%;margin:0 auto;-moz-border-radius:2px;-webkit-border-radius:2px;border-radius:2px;}
#feedNav a:hover {background-color:#2E2E2E;}

/* Others and Input Method
----------------------------------------------- */
img {max-width:100%;height:auto;width:auto\9;}
a img, .buttons a, .post-outer.list .post-more-link a, #feedContainer .date{-webkit-transition:all .4s ease-in-out;-moz-transition:all .4s ease-in-out;-o-transition:all .4s ease-in-out;-ms-transition:all .4s ease-in-out;transition:all .4s ease-in-out;}
a img:hover {-ms-filter:"progid:DXImageTransform.Microsoft.Alpha(Opacity=70)";filter:alpha(opacity=70);-moz-opacity:0.7;-khtml-opacity:0.7;opacity:0.7;}
input[type="submit"] {border-radius:2px;background-color:$keycolor;outline:0;border:0;padding:5px 8px;color:#fff;margin:2px 3px;cursor:pointer;}
input[type="submit"]:hover {background-color:#2E2E2E;}
input[type="text"] {padding:4px 5px;border:1px solid #B6B6B6;border-radius:2px;color:#585858;}

/* Playlist
----------------------------------------------- */
.Sd_control .active{background-color: $keycolor;}
.Sd_list .selected {background-color: #3A3A3A;border-left: 5px solid $keycolor;border-right: 2px solid $keycolor;}
.Sd_list li:hover{border-left: 5px solid $keycolor;background:#0F1010;}

/* Footer
----------------------------------------------- */
#footer-wrapper {margin: 0 auto;margin-bottom:-27px;overflow: hidden;padding: 20px 20px;border-top: 5px solid $(footer.bordertop.color);font-size:16px;background:#2E2E2E;font-weight:600;}
.footer-left {float: left;color:$(footer.text.color)}
.footer-right {float: right;color:$(footer.text.color);font-family: 'kantumruy';}

/* Rating Area */
.rateContent,.rateContent .rating-bar,.rating-area{text-align:center;overflow:hidden}.rating-area{position:relative;display:block;margin-top:10px;line-height:normal}.rt{overflow:hidden;margin-bottom:11px;padding:9px;border-radius:3px;background:#151515;border:1px solid #151515}.rt span{color:#fff}.rt span[itemprop=ratingValue]{font-weight:700;font-size:18px}.rt span[itemprop=ratingCount]{font-size:11px}.rateContent{margin-top:9px}.rateContent .rating-bar{position:relative;height:16px;color:#ffe203;outline:0;width:100px;float:none;display:inline-block}.rateContent .rating-bar:before{content:"";position:absolute;top:-1px;left:0;background:url("data:image/svg+xml,%3Csvg viewBox='0 0 24 24' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M12,17.27L18.18,21L16.54,13.97L22,9.24L14.81,8.62L12,2L9.19,8.62L2,9.24L7.45,13.97L5.82,21L12,17.27Z' fill='%23ddd'/%3E%3C/svg%3E") 20px;min-width:100%;min-height:20px}.rateContent .rating-bar span{overflow:hidden;top:0;left:0;position:absolute;padding-top:20px}.rateContent .rating-bar span:before{content:"";position:absolute;top:-1px;left:0;background:url("data:image/svg+xml,%3Csvg viewBox='0 0 24 24' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M12,17.27L18.18,21L16.54,13.97L22,9.24L14.81,8.62L12,2L9.19,8.62L2,9.24L7.45,13.97L5.82,21L12,17.27Z' fill='%23ffc107'/%3E%3C/svg%3E") 20px;min-width:100%;min-height:20px}

/* Sinopsis */
.dagruel-sinopsis{overflow:hidden;z-index:99;background:#2e2e2e;margin-bottom:20px;border-bottom:1px solid #f1f1f1}.dagruel-sinopsis .left{.float:left;padding:10px}.dagruel-sinopsis .right{overflow:hidden;padding:10px}.sinojudul{overflow:hidden;margin:5px;border-bottom:1px solid #eceff5;padding-bottom:13px}.judul h1{font-size:24px;font-weight:600;line-height:-6px;color:#fff;float:left;display:contents;margin:0 0 5px}.judul span.trailer{padding:7px;margin-left:5px;font-size:13px;line-height:28px;display:inline-block}.judul span.trailer a svg{color:#ef5350;width:23.63px !important;position: relative;top: 6px;margin-right: 1px;height: auto !important;}.alternaiv{color:#333;overflow:hidden;width:100%;font-weight:500}.alternaiv span{font-size:13px;line-height:20px;padding-right:13px;display:inline-block;float:left}.alternaiv span:after{content:"/";padding-left:11px}.alternaiv span:last-child:after{content:""}.desc{line-height:1.4em;color:#888}.desc h3{font-size:17px;font-weight:600;color:#fff;margin:0 0 10px}.desc p{margin:0 0 10px;overflow:hidden;font-size:14px;font-weight:400;color:#ddd;line-height:26px}.genre-info{display:block;margin-top:10px}.genre-info span{padding:0 10px;display:-webkit-inline-box;margin-right:7px;margin-bottom:6px;font-size:13px;border-radius:4px;background:#f5f7fa}.genre-info span:hover{background-color:#0c70de;color:#fff}.genre-info span a:hover{color:#fff}@media screen and (max-width:875px){.dagruel-sinopsis .left{text-align:center;float:none}.dagruel-sinopsis .right{padding:0}.sinojudul{text-align:center}.desc{margin-left:5px}}

/* Information */
.infox{background-color:#f1f1f1;border-radius:7px;margin-bottom:20px;border-bottom:1px solid #f1f1f1}.infox .spe span:not(:last-of-type),h3.anim-detail{border-bottom:1px solid #040404}h3.anim-detail{background:#2e2e2e;font-weight:600;padding:0 10px 10px;margin:0;font-size:20px;color:#fff}.infox .spe{overflow:hidden;font-size:12px;background:#2e2e2e}.infox .spe span{padding-left:9px;width:47%;margin-right:1%;float:left;position:relative;font-size:14px;line-height:28px;text-overflow:clip;white-space:nowrap;overflow:hidden;padding-bottom:5px;padding-top:5px;color:#dadadb}.infox .spe span:hover{background:#f1f1f14f}.infox .spe b{font-weight:500;overflow:hidden;min-width:117px;float:left;border-right:1px solid #000;margin-right:10px}@media screen and (max-width:920px){.infox .spe span{width:100%!important}}

.thumbimgx:hover::after {
	content: '\f144';
	position: absolute;
	top: 50%;
	left: 50%;
	font-family: 'Font Awesome 5 free';
	font-size: 3rem;
	font-weight: 400;
	z-index: 9999;
	transform: translate(-50%,-50%);
	color: white;
	text-shadow: 1px 2px 3px #424242;
}

/* Preloader By Rean Blog
----------------------------------------------- */
#page-loader {position:fixed !important;position:absolute;top:0;right:0;bottom:0;left:0;z-index:9999;display:none;background:#09111f url('https://cdn.dribbble.com/users/563824/screenshots/3114148/good-1.gif') no-repeat 50% 50%;padding:1em 1.2em;} 

/* Media Queries
----------------------------------------------- */
@media only screen and (max-width:1100px) {
  #nav {max-width:100%;margin:0 auto;left:0px;right:0px;}
  ul#related-summary li{margin:5px !important;}
  #header {width:100%;float:none;text-align:center;}
  #header img {margin:0 auto;}
  #header-right{max-width:1100px;float:none;text-align:center;height:auto;margin:15px auto;clear:both}
  #ads-top, #ads-bottom{float:none;width:98%;text-align:center;height:auto;margin:14px auto;clear:both}
}
@media only screen and (max-width:1024px) {
  #navinti a {padding:0 10px;}
  #searchkh {width: 195px;}
  #ajax-search-form {width: 191px;}
  #ajax-search-form input {width: 140px;}
}
@media only screen and (max-width:979px) {
  #outer-wrapper, #nav {width:768px;}
  #nav .wrap {width: 99%;}
  #footer-wrapper .grid {width:33.3%;} 
  #topmenunav, #menunav, .kh-menu a.home:before, .kh-menu > li > a.home.current:before {display:none;}
  #topmobilenav, #mobilenav {display:block;}
  #menunav, #topmenunav {position: absolute;top: 100%;float: none;left: 5px;}
  #menunav {background-color: #2E2E2E;right: 5px;}
  #topmenunav {width: 300px;background-color: #1A1A1A;z-index: 99;}
  .kh-menu > li {float: none;}
  .kh-menu ul {position: static;}
  .kh-menu ul ul li {margin: 1px 0;}
  .kh-menu a.home, .kh-menu > li > a.home.current {text-indent: 0;width: auto;padding: 0 10px;}
  #menunav > li > a {height: 30px;line-height: 30px;}
  #topnav .tgltop {margin-left: 35px;}
  .kh-menu li:hover > ul, .kh-menu li.khHover > ul {display:none;}
  #main-content {width:100%;}
  #sidebar-wrapper {width:42%;}
  .index .post-outer, .archive .post-outer{width:50%;}
  .post-outer.list a.thumbimgx {width:150px;height:120px;}
  .post-body .left, .post-body .right {display:block;text-align:center;margin:10px 0 15px;}    
  .comments .comments-content .comment-replies {margin-left:10px;}
  #header {width:100%;float:none;text-align:center;}
  #header img {margin:0 auto;}    
  #feedContainer li {float:none;width:100%;}
  #feedContainer .inner {height:auto;}
  ul#related-summary li{margin:5px !important;width: 46.2% !important;}
  #ads-top, #ads-bottom, #header-right{float:none;width:96%;text-align:center;height:auto;margin:14px auto;clear:both}
  .smoothscroll-top{display:none;}
  #notification{display:none}
  #sliding_box{display:none;}
}
@media only screen and (max-width:880px) {
  #outer-wrapper, #nav {width:100%;}
  #footer-wrapper .grid {width:50%;}
  #main-content, #sidebar-wrapper {width:98%;float:none;padding:0 1%;}   
  #header {text-align:center;}
  #header img {margin:0 auto;}
  .section, .widget{margin:-1px}
  .post .titlex{margin:-3px}
  .timeline-bar{margin:0px 4px 0px 4px;}
  .pagenavi{margin:0 5px 0 10px}
  .PopularPosts .item-thumbnail {margin: -13px 0px 0px 7px;}
  .popular-posts ul li img{width:100%;height: 190px;padding:2px;}
  #topmenunav {right: 5px;width: auto;}
	/* My css */
	.index .post-outer, .archive .post-outer {width: 20%;}
ul#related-summary li {
	margin: 5px !important;
	width: 30.77% !important;
}
}
@media screen and (max-width: 680px){
  ul#related-summary li{width: 45%;height: auto;display:inline-block;}
  ul#related-summary li a.relinkjdulx{position:absolute;bottom:0;}
/* My css */	
.index .post-outer, .archive .post-outer {width: 33.3333%;}
}
@media only screen and (max-width:479px) {
  #outer-wrapper, #nav {width:100%;}
  #content-wrapper {margin:0 auto;width:100%;}
  #footer-wrapper .grid {width:100%;}
  a.thumbimgx {padding:0px;height:140px;}
  .index .post-outer .post, .archive .post-outer .post {height:190px;}
  .post-outer.list a.thumbimgx {width:120px;height:90px;}
  .post-outer.list .post .titlex {font-size:130%;}
  .PopularPosts .item-thumbnail{margin: -24px 0px 0px 0px;}
  .popular-posts ul li img{width: 95%;height: 140px;padding: 4px;}
  .separator a, table.tr-caption-container {float:none !important;margin:0 auto 15px !important;}
  table.tr-caption-container {padding:0;}
  #search-result, .box, .box .antiscroll-inner {width:272px;}  
  #topnav .tgltop {display: none;}
  .Sd_control {font-size:14px !important;}
}
@media only screen and (max-width:319px) {
  #outer-wrapper, #nav {width:100%;}
  .index .post-outer, .archive .post-outer, ul.rcentpost.sliderq li {width:100%;float:none;}
  #search-result, .box, .box .antiscroll-inner {width:250px;}  
}
}

#rithiseth {
color: transparent;
}
#rithiseth a {
color: transparent;
}

#rithiseth a:link {
color: transparent;
}

head.b:template-skin:
html body#layout{background-color: #f1f1f1;  border: 4px solid #1ec7e9;}
html body#layout:before{content:" ";width:100%;height:87px;top:0;position:absolute;display:block;background-position:50%;background-repeat:no-repeat;background-image:url('https://3.bp.blogspot.com/-1XWeKeFufq4/WVZtyfrFRjI/AAAAAAAACIE/p5Bqz_MJsF4RYex6afmBQ4HjHj7y8HD_gCLcBGAs/s1600/themelogo.png')}
body#layout .locked-widget .widget-content{background-color:#fff;box-shadow:1px 2px 2px 1px rgba(0,0,0,.2)}
body#layout .editlink {color:#fff !important;background:#1ec7e9;padding: 2px; padding-left: 15px; padding-right: 15px; border-radius: 4px}
body#layout .visibility .editlink.icon{margin-right:-6px;padding:1px 25px!important;height:30px!important; top:auto!important;}
body#layout div.layout-title{color:#444}
body#layout div.layout-widget-description{color:#d9ac33}
html body#layout .dropregion{opacity:0.5;background-image:url("https://3.bp.blogspot.com/-1XWeKeFufq4/WVZtyfrFRjI/AAAAAAAACIE/p5Bqz_MJsF4RYex6afmBQ4HjHj7y8HD_gCLcBGAs/s1600/themelogo.png");background-color:rgb(225,190,231);background-position:50% 50%;background-repeat:no-repeat}
html body#layout div.section{background-color:#1ec7e9;border-radius:3px;border:none}
html body#layout .add_widget{1px dashed #FF4081}
body#layout .add_widget a{color:#fff}
html body#layout .add_widget .add-icon{background-color:#FFFFFF;border-radius:50%;transition:width 1s ease-in-out}
html body#layout .draggable-widget .widget-wrap2{background-color:#CDDC39}
body#layout #header-wrapper{height:100%;position:relative;top:-50px}
body#layout header{width:auto}
body#layout #main-wrapper{display:inline-block;float:left;width:99%;margin:0px 0 0 0}
body#layout #ads-top{display:inline-block;float:left;width:99%;margin:4px 3px;padding:16px 0;margin-right:-7px;position:relative;top:12px;}
body#layout #ads-bottom{display:inline-block;float:left;width:99%;margin:4px 3px;padding:16px 0;margin-right:-7px}
body#layout #header-right{width:55%;margin:4px;float:right;background-color:#1ec7e9;padding:13px!important; border: 3px double #fff;}
body#layout .section h4{text-align:center;text-transform:uppercase;color:#fff}
body#layout #main-content{margin-top:-123px !important;}
body#layout #content-wrapper{padding:0px !important;}

